def utf16be_hex(text, bom=False):
    prefix = '﻿' if bom else ''
    return '<' + (prefix + text).encode('utf-16-be', 'replace').hex().upper() + '>'


def utf16_code_units(text):
    # Non-BMP characters become surrogate pairs; each surrogate acts as a CID
